(6687373, 999425, 10785, '<td valign="top">Good light. The color is a little off because the background has reflected the green light on the subject. It also looks like there is some camera shake going on here because the image is a tad blurry?</td>', 'Good light. The color is a little off because the background has reflected the green light on the subject. It also looks like there is some camera shake going on here because the image is a tad blurry?', '2012-02-22 13:26:30.000000', NULL, 1),
(6687374, 1000382, 7327, '<td valign="top">I like the set-up, it must have been a full-filling contest to enter for you.</td>', 'I like the set-up, it must have been a full-filling contest to enter for you.', '2012-02-22 13:26:38.000000', NULL, 1),
(6687375, 1000287, 112739, '<td valign="top">My head hurts when I have to turn it that way. No title?</td>', 'My head hurts when I have to turn it that way. No title?', '2012-02-22 13:27:53.000000', NULL, 1),
(6687376, 999822, 7327, '<td valign="top">Interesting shot, I hope you post the details after the contest is over.</td>', 'Interesting shot, I hope you post the details after the contest is over.', '2012-02-22 13:28:03.000000', NULL, 1),
(6687377, 1000324, 10785, '<td valign="top">The flash in the shoe is an odd choice here...</td>', 'The flash in the shoe is an odd choice here...', '2012-02-22 13:28:06.000000', NULL, 1),
(6687379, 999689, 112739, '<td valign="top">Paw print is not footwear. Footwear is something that one wears on ones feet. I think this could be improved if taken from a different perspective. Maybe down low and have an interesting subject in the BG. As it is now, it''s not very interesting.</td>', 'Paw print is not footwear. Footwear is something that one wears on ones feet. I think this could be improved if taken from a different perspective. Maybe down low and have an interesting subject in the BG. As it is now, it''s not very interesting.', '2012-02-22 13:30:07.000000', NULL, 1),
