(6687382, 999628, 10785, '<td valign="top">Very humorous!!</td>', 'Very humorous!!', '2012-02-22 13:31:16.000000', NULL, 1),
(6687384, 999344, 112739, '<td valign="top">Cool shot! Guess I might like to see a little more light on upper part of the shoe, but otherwise a fantastic job.</td>', 'Cool shot! Guess I might like to see a little more light on upper part of the shoe, but otherwise a fantastic job.', '2012-02-22 13:33:13.000000', NULL, 1),
(6687392, 999344, 131871, '<td valign="top">Awesome angle!</td>', 'Awesome angle!', '2012-02-22 13:39:42.000000', NULL, 1),
(6687404, 1000316, 67258, '<td valign="top">Goodness, I''m not surprised wearing shoes is difficult!  I hope you are able to get proper care for your feet :(  On a photographic note, crisp focus - just the right depth of field, and in a rather voyeuristic way, an intersting image.  Take care!</td>', 'Goodness, I''m not surprised wearing shoes is difficult!  I hope you are able to get proper care for your feet :(  On a photographic note, crisp focus - just the right depth of field, and in a rather voyeuristic way, an intersting image.  Take care!', '2012-02-22 13:48:08.000000', NULL, 1),
(6687409, 999710, 67258, '<td valign="top">Looks like a verbena to me, unless croccus is the type of shoe?  Technically sound, but for me you haven''t quite pulled your concept off.</td>', 'Looks like a verbena to me, unless croccus is the type of shoe?  Technically sound, but for me you haven''t quite pulled your concept off.', '2012-02-22 13:49:43.000000', NULL, 1),
(6687416, 1000326, 112739, '<td valign="top">Very nice. A winner. Perfect comp. Lovely tones. Nice story. Big Congrats. Like my 2 word comments?</td>', 'Very nice. A winner. Perfect comp. Lovely tones. Nice story. Big Congrats. Like my 2 word comments?', '2012-02-22 13:55:05.000000', NULL, 1),
(6687417, 1000336, 112739, '<td valign="top">Also very nicely done. I am scoring this high as well.</td>', 'Also very nicely done. I am scoring this high as well.', '2012-02-22 13:56:25.000000', NULL, 1),
(6687425, 999689, 67258, '<td valign="top">Out of the box entry, but technically lacking.  Lighting is very harsh, and composition static resulting in a straight record shot of a pawprint.  Using early morning light, or late afternoon, you would be able to bring out some of the textural detail.</td>', 'Out of the box entry, but technically lacking.  Lighting is very harsh, and composition static resulting in a straight record shot of a pawprint.  Using early morning light, or late afternoon, you would be able to bring out some of the textural detail.', '2012-02-22 14:08:12.000000', NULL, 1),
(6687427, 1000255, 67258, '<td valign="top">Wendy?  A whimsical and rather sweet image that is technically really well done.  Love the colour of the background bokeh.</td>', 'Wendy?  A whimsical and rather sweet image that is technically really well done.  Love the colour of the background bokeh.', '2012-02-22 14:09:44.000000', NULL, 1),
